-- Generated by Ingestron from flows/crm.yaml (table contacts). Do not edit: change the definitions and generate again.
-- Changes as received, each read once.
CREATE OR REFRESH STREAMING TABLE `dev`.`bronze`.`contacts_changes`
AS SELECT * FROM STREAM read_files(
  '/Volumes/dev/landing/crm/changes/contacts',
  format => 'json',
  schemaHints => '`account_id` STRING, `contact_id` STRING, `email` STRING, `changed_at` TIMESTAMP, `operation` STRING',
  schemaEvolutionMode => 'addNewColumns'
);

-- The current rows, with history, kept by key.
CREATE OR REFRESH STREAMING TABLE `dev`.`bronze`.`contacts` (
  CONSTRAINT `account_id_not_null` EXPECT (`account_id` IS NOT NULL),
  CONSTRAINT `contact_id_not_null` EXPECT (`contact_id` IS NOT NULL),
  CONSTRAINT `changed_at_not_null` EXPECT (`changed_at` IS NOT NULL)
)
COMMENT 'Contacts with every past version.'
CLUSTER BY AUTO;

CREATE FLOW `contacts_cdc`
AS AUTO CDC INTO `dev`.`bronze`.`contacts`
FROM STREAM(`dev`.`bronze`.`contacts_changes`)
KEYS (`account_id`, `contact_id`)
SEQUENCE BY `changed_at`
COLUMNS * EXCEPT (`operation`)
STORED AS SCD TYPE 2;
